contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint d, uint amount) public payable {
        require(d > 0);
        require(amount > 0);
        require(amount <= d);
        require(address(this).balance >= d);
        c.SetMinSum(0);
        c.Deposit{value: d}();
        uint balBefore = c.balances(address(this));
        uint ethBefore = address(c).balance;
        bool reverted;
        try c.Collect(amount) { reverted = false; } catch { reverted = true; }
        assert(!reverted
            && c.balances(address(this)) == balBefore - amount
            && address(c).balance == ethBefore - amount);
    }
    receive() external payable {}
}

